    <title>动态</title>
    <style>
        :root {
            /* JK辣妹风：柔粉 + 微暖 + 低对比，避免刺眼 */
            --primary: #ff8fb8;           /* 樱花粉主色 */
            --text: #4a4a4a;              /* 柔和深灰文字 */
            --bg: transparent;            /* 最底层完全透明 */
            --card: #fffafc;              /* 极微暖白卡片，降低亮度 */
            --content-bg: #fdf6f9;        /* 正文区域柔粉底，比纯白柔和 */
            --border: #ffe5f0;            /* 极浅粉边框 */
            --shadow: 0 6px 20px rgba(255, 143, 184, 0.1); /* 更淡的粉影 */
            --divider: #ffd6e8;           /* 柔粉分隔 */
        }
        * {
            box-sizing: border-box;
        }
        body {
            background: var(--bg);       /* 完全透明，适配任意背景 */
            padding: 20px;
            max-width: 480px;
            margin: 0 auto;
            font-family: "Hiragino Sans", "Microsoft YaHei", "PingFang SC", sans-serif;
            color: var(--text);
            line-height: 1.6;
        }
        .p {
            background: var(--card);
            border-radius: 22px;
            overflow: hidden;
            margin-bottom: 20px;
            box-shadow: var(--shadow);
            transition: all 0.3s ease;
            border: 1px solid var(--border);
        }
        .p:hover {
            transform: translateY(-4px);
            box-shadow: 0 14px 32px rgba(255, 143, 184, 0.15);
        }
        /* 头部：柔和渐变 */
        .h {
            padding: 18px 20px 14px;
            background: linear-gradient(135deg, #fff8fc 0%, #fdf6f9 100%);
            border-bottom: 2px solid var(--divider);
        }
        .u h3 {
            font-size: 19px;
            font-weight: 700;
            color: var(--primary);
            margin: 0;
            letter-spacing: 0.6px;
            text-shadow: 0 1px 1px rgba(255, 143, 184, 0.12);
        }
        /* 正文区域：降低亮度 + 柔粉底 */
        .c {
            padding: 20px 20px 16px;
            background: var(--content-bg); /* 柔粉底，不刺眼 */
            position: relative;
        }
        .c::before {
            content: "";
            position: absolute;
            top: 0; left: 20px; right: 20px; height: 1px;
            background: linear-gradient(90deg, transparent, var(--divider), transparent);
        }
        .t {
            font-size: 16px;
            line-height: 1.78;
            color: #3a3a3a;               /* 更柔和文字色 */
            margin: 0 0 15px 0;
            word-break: break-word;
            letter-spacing: 0.3px;
        }
        .i {
            min-height: 10px;
        }
        /* 评论区：柔和渐变底 */
        .live-comments {
            padding: 18px 20px;
            border-top: 1px dashed var(--divider);
            background: linear-gradient(to bottom, #fff9fc, #fdf6f9);
            border-bottom-left-radius: 22px;
            border-bottom-right-radius: 22px;
            max-height: 160px;
            overflow-y: auto;
            font-size: 14.3px;
            line-height: 1.95;
        }
        .live-comments::-webkit-scrollbar {
            width: 4px;
        }
        .live-comments::-webkit-scrollbar-track {
            background: transparent;
        }
        .live-comments::-webkit-scrollbar-thumb {
            background: #ffd6e8;
            border-radius: 2px;
        }
        .live-comments::-webkit-scrollbar-thumb:hover {
            background: var(--primary);
        }
        .comment-line {
            display: block;
            margin-bottom: 10px;
            padding-left: 2px;
        }
        .comment-line:last-child {
            margin-bottom: 0;
        }
        .cn {
            font-weight: 700;
            color: var(--primary);
            margin-right: 5px;
            font-size: 14.6px;
        }
        .ct {
            color: #555;                  /* 更柔和评论文字 */
        }
        .live-comments:empty::after {
            content: "暂无评论～";
            color: #dd99bb;
            font-size: 13.8px;
            text-align: center;
            display: block;
            padding: 22px 0;
            font-style: italic;
        }
    </style>
</head>
<body>
    <div class="p">
        <!-- 头部 -->
        <div class="h">
            <div class="u">
                <h3>$1</h3>
            </div>
        </div>
        <!-- 正文 -->
        <div class="c">
            <div class="t">$2</div>
            <div class="i"></div>
        </div>
        <!-- 评论区：垂直排列 + 美化 -->
        <div class="live-comments" id="comments-body">
            <pre style="display:none;">$3</pre>
        </div>
    </div>
    <script>
        // 保留原始 <pre> 结构，但通过 JS 转为垂直美化排布
        document.addEventListener('DOMContentLoaded', () => {
            const container = document.getElementById('comments-body');
            const pre = container.querySelector('pre');
            if (!pre) return;
            const text = pre.textContent.trim();
            pre.style.display = 'none'; // 隐藏原始 pre
            if (!text) {
                return;
            }
            const lines = text.split('\n').map(l => l.trim()).filter(Boolean);
            const html = lines.map(line => {
                const match = line.match(/^([^：]+)：\s*(.+)$/);
                if (match) {
                    const name = match[1].trim();
                    const content = match[2].trim();
                    return `<div class="comment-line"><span class="cn">${name}</span><span class="ct">：${content}</span></div>`;
                }
                return `<div class="comment-line">${line}</div>`;
            }).join('');
            container.innerHTML += html;
        });
    </script>
</body>
</html>
