            color: var(--text);
            line-height: 1.6;
        }
        .p {
            background: var(--card);
            border-radius: 22px;
            overflow: hidden;
            margin-bottom: 20px;
            box-shadow: var(--shadow);
            transition: all 0.3s ease;
            border: 1px solid var(--border);
